sql.where:
uar.delete_flag = false

    and uar.it_code_of_user = #{useAccessReviewBean.itCodeOfUser}


    and iad.application_name = #{useAccessReviewBean.appName}


    and uar.cmdb_id = #{useAccessReviewBean.cmdbId}


    and uar.line_manager = #{useAccessReviewBean.lineManager}




            AND (uar.bpo IS NULL or uar.bpo = '')


            AND uar.bpo ~* '\y(${useAccessReviewBean.bpo})\y'




    and uar.line_manager_review_status = #{useAccessReviewBean.lineManagerReviewStatus}


    AND uar.line_managers_review_decision = #{useAccessReviewBean.lineManagersReviewDecision}



    AND uar.bpo_review_status = #{useAccessReviewBean.bpoReviewStatus}


    AND uar.bpo_review_decision = #{useAccessReviewBean.bpoReviewDecision}



    AND uar.final_review_decision = #{useAccessReviewBean.finalReviewDecision}







        AND uar.cmdb_id in (

            #{item}

        )



    AND iad.uar_processor ~* '\y(${useAccessReviewBean.uarProcessor})\y'


    AND iad.operation_owner = #{useAccessReviewBean.appOperationOwner}




            AND iad.operation_focal IS NULL


            AND iad.operation_focal = #{useAccessReviewBean.appOperationFocal}




    AND iad.operation_owner_domain = #{useAccessReviewBean.operationOwnerDomain}


    AND iad.operation_owner_tower = #{useAccessReviewBean.operationOwnerTower}


    AND uar.line_manager_level_code = #{useAccessReviewBean.lineManagerLevelCode}


    AND uar.maintenance_id = #{useAccessReviewBean.currentDataCycle}

mapper.select:
SELECT
count(1) AS total,
COUNT(*) FILTER (
    WHERE line_manager_review_status = '2' AND bpo_review_status = '2'
) AS reviewed,
COALESCE( ROUND(
    COUNT(*) FILTER (
        WHERE line_manager_review_status = '2' AND bpo_review_status = '2'
    ) * 100.0 / NULLIF(COUNT(*), 0), 2
), 0.00 ) AS completionRate,
COALESCE( ROUND(
    COUNT(*) FILTER (
        WHERE line_manager_review_status = '2'
    ) * 100.0 / NULLIF(COUNT(*), 0), 2
), 0.00 ) AS lineManagerResponseRate,
COALESCE( ROUND(
    COUNT(*) FILTER (
        WHERE bpo_review_status = '2'
    ) * 100.0 / NULLIF(COUNT(*), 0), 2
), 0.00 ) AS bpoResponseRate

FROM

    user_access_review_history uar


    user_access_review uar


    delete_flag = false





            AND cmdb_id in (

                #{item}

            )



        AND uar.maintenance_id = #{currentDataCycle}

mapper.sql:
SELECT
uar.cmdb_id as cmdbId,
min(iad.application_name) as applicationName,
min(iad.operation_owner) AS appOperationOwner,
min(iad.operation_focal) AS appOperationFocal,
min(iad.operation_owner_domain) AS operationOwnerDomain,
min(iad.operation_owner_tower) AS operationOwnerTower,

count(1) AS total,
COUNT(*) FILTER (
    WHERE line_manager_review_status = '2' AND bpo_review_status = '2'
) AS reviewed,
COUNT(*) FILTER (
    WHERE line_manager_review_status = '1' OR bpo_review_status = '1'
) AS pendingReview,
COALESCE( ROUND(
    COUNT(*) FILTER (
        WHERE line_manager_review_status = '2' AND bpo_review_status = '2'
    ) * 100.0 / COUNT(*), 2
), 0.00 ) AS completionRate,
COALESCE( ROUND(
    COUNT(*) FILTER (
        WHERE line_manager_review_status = '2'
    ) * 100.0 / COUNT(*), 2
), 0.00 ) AS lineManagerResponseRate,
COALESCE( ROUND(
    COUNT(*) FILTER (
        WHERE bpo_review_status = '2'
    ) * 100.0 / COUNT(*), 2
), 0.00 ) AS bpoResponseRate,
COUNT(*) FILTER (WHERE final_review_decision = 'keep') AS keep,
COALESCE( ROUND( COUNT(*) FILTER (
        WHERE final_review_decision = 'keep') * 100.0 /
        NULLIF(COUNT(*) FILTER ( WHERE line_manager_review_status = '2' AND bpo_review_status = '2'), 0)
, 2 ), 0.00 ) AS keepRate,
COUNT(*) FILTER (WHERE line_manager_review_status = '2' AND bpo_review_status = '2' AND final_review_decision = 'remove') AS remove,
COALESCE( ROUND( COUNT(*) FILTER (
    WHERE line_manager_review_status = '2' AND bpo_review_status = '2' AND final_review_decision = 'remove') * 100.0 /
        NULLIF(COUNT(*) FILTER ( WHERE line_manager_review_status = '2' AND bpo_review_status = '2'), 0)
, 2 ), 0.00 ) AS removeRate

FROM

    user_access_review_history uar


    user_access_review uar

LEFT JOIN its_application_data iad ON uar.cmdb_id = iad.cmdb_id

    uar.delete_flag = false

        AND uar.cmdb_id = #{search.cmdbId}


        AND iad.application_name = #{search.appName}


        AND iad.operation_owner = #{search.appOperationOwner}




                AND iad.operation_focal IS NULL


                AND iad.operation_focal = #{search.appOperationFocal}




        AND iad.operation_owner_domain = #{search.operationOwnerDomain}


        AND iad.operation_owner_tower = #{search.operationOwnerTower}






            AND uar.cmdb_id in (

                #{item}

            )



        AND uar.maintenance_id = #{search.currentDataCycle}


GROUP BY
uar.cmdb_id
order by


        ${search.sortField}


        uar.cmdb_id




        ${search.sortOrder}


        ASC

mapper.select:
SELECT CASE line_manager_level_code WHEN '1' THEN 'Below' WHEN '2' THEN 'ED' WHEN '3' THEN 'VP' WHEN '4' THEN 'Above' END AS level, COUNT(*) AS totalPerson, SUM(item_cnt) AS totalItems, SUM(CASE WHEN dedup.is_all_completed THEN 1 ELSE 0 END) AS completedPerson, SUM(CASE WHEN NOT dedup.is_all_completed THEN 1 ELSE 0 END) AS uncompletedPerson FROM ( SELECT line_manager, line_manager_level_code, COUNT(*) AS item_cnt, BOOL_AND(line_manager_review_status = '2') AS is_all_completed FROM
user_access_review_history uar
user_access_review uar
delete_flag = false AND line_manager_level_code IS NOT NULL
AND cmdb_id in (
#{item}
)
AND uar.maintenance_id = #{currentDataCycle}
GROUP BY line_manager, line_manager_level_code ) AS dedup GROUP BY line_manager_level_code

mapper.sql:
uar.delete_flag = false

    AND uar.cmdb_id = #{search.cmdbId}


    AND (
        EXISTS (
            SELECT 1
            FROM its_application_data app_filter
            WHERE app_filter.cmdb_id = uar.cmdb_id
              AND app_filter.application_name = #{search.appName}
        )
        OR (
            uar.app_name = #{search.appName}
            AND NOT EXISTS (
                SELECT 1
                FROM its_application_data app_exists
                WHERE app_exists.cmdb_id = uar.cmdb_id
                  AND app_exists.application_name IS NOT NULL
            )
        )
    )






        AND uar.cmdb_id IN (

            #{item}

        )



    AND uar.maintenance_id = #{search.currentDataCycle}
